  openContext({kind,id,event}){const items=kind==='slot'?[{icon:'↗',label:'打开 / 进入',action:()=>this.activate({kind,id})},{icon:'◇',label:'引用已有 Knowledge',action:()=>this.openPicker(id)},{icon:'＋',label:'新建并引用',action:()=>this.openQuickCreate({instanceId:this.currentInstanceId,slotId:id})},{icon:'◫',label:'展开嵌套 Structure',action:()=>this.openPicker(id,true)},{separator:true},{icon:'☷',label:'节点属性',action:()=>this.openPanel('slot',id)},{icon:'C',label:'从这里连接',action:()=>{this.setMode('connect');this.connectSource=id}},{separator:true},{icon:'⌫',label:'移除节点',danger:true,disabled:this.mode!=='edit',action:()=>this.removeSlot(id)}]:kind==='edge'?[{icon:'☷',label:'关系属性',action:()=>this.openPanel('edge',id)},{icon:'⇄',label:'反转方向',action:()=>this.reverseEdge(id)},{icon:'↝',label:'切换路由',action:()=>this.cycleRouting(id)},{separator:true},{icon:'⌫',label:'删除关系',danger:true,disabled:this.mode!=='edit',action:()=>this.removeEdge(id)}]:kind==='canvas'?[{icon:'＋',label:'添加节点',disabled:this.mode!=='edit',action:()=>this.addSlot()},{icon:'C',label:'连接模式',action:()=>this.setMode('connect')},{icon:'⌗',label:'适合窗口',action:()=>this.fit()},{icon:'⬡',label:'结构属性',action:()=>this.openPanel('structure',this.currentInstanceId)},{separator:true},{icon:'↧',label:'导出当前 Structure',action:()=>this.exportAs('lkl')}]:[];this.showContextMenu(event.clientX,event.clientY,items)}
  showContextMenu(x,y,items){const root=$('#contextMenu');root.replaceChildren();for(const item of items){if(item.separator){root.append(document.createElement('hr'));continue}const button=document.createElement('button');button.disabled=!!item.disabled;button.classList.toggle('danger',!!item.danger);button.innerHTML=`<span>${item.icon??''}</span><span>${escapeHtml(item.label)}</span><kbd>${item.shortcut??''}</kbd>`;button.onclick=()=>{this.hideContextMenu();item.action?.()};root.append(button)}root.classList.remove('hidden');const width=220,height=Math.min(420,items.length*38);root.style.left=`${Math.min(x,innerWidth-width-8)}px`;root.style.top=`${Math.min(y,innerHeight-height-8)}px`}
