  addSlot(){if(!this.instance)return;let slot;this.commit('slot:add',()=>{slot=addInstanceSlot(this.instance,{label:'新节点',role:'custom'});this.selection=new Set([`slot:${slot.id}`])});this.openPanel('slot',slot.id)}
  removeSlot(id){if(this.mode!=='edit')return;this.commit('slot:remove',()=>removeInstanceSlot(this.instance,id));this.selection.delete(`slot:${id}`);this.closePanel()}
