  openPanel(kind,id,tab='info'){this.panel={kind,id,tab};$('#floatingPanel').classList.remove('hidden');this.renderPanel()}
  closePanel(){$('#floatingPanel').classList.add('hidden');this.panel={kind:null,id:null,tab:'info'}}
  renderPanel(){const {kind,id}=this.panel;if(!kind)return;const titles={slot:'节点',edge:'关系',structure:'Structure'};$('#panelEyebrow').textContent=kind.toUpperCase();$('#panelTitle').textContent=kind==='structure'?this.template?.name:this.currentDefinition?.[kind==='slot'?'slots':'edges']?.find(item=>item.id===id)?.label||titles[kind];const tabs=kind==='structure'?[['info','信息'],['parameters','参数'],['variables','变量'],['history','历史']]:kind==='slot'?[['info','信息'],['bindings','引用'],['geometry','几何']]:[['info','关系'],['appearance','线型']];const tabRoot=$('#panelTabs');tabRoot.replaceChildren();for(const[value,label]of tabs){const button=document.createElement('button');button.textContent=label;button.classList.toggle('active',value===this.panel.tab);button.onclick=()=>{this.panel.tab=value;this.renderPanel()};tabRoot.append(button)}this.renderPanelContent()}
